import React, { useState,useEffect } from "react";
import { useNavigate } from "react-router-dom";
import {socket} from '../services/socket.js';


  const HandleJoin = ({name,setCopied}) => {
    const navigate = useNavigate();
    if (!name.trim()) {
      alert("Please enter your name");
      return;
    }

    socket.emit("create-room", { name }, (response) => {
      const roomId = response.roomCode;
    const URL = window.location.origin + `/game/${roomId}`;
    console.log(URL);
    navigator.clipboard.writeText(URL);
    setCopied(true)
    navigate(`/game/${roomId}`);
    });

    console.log(name);
  };
  export default function EnterName({ onClose, roomCode, setRoomCode }) {
    const [name, setName] = useState("");
useEffect(()=>{
    if(copied){
        return(
<div> Copied the Link </div>
        )
    }
})
    const [copied, setCopied] = useState(false);
    return (
      <div className="fixed inset-0 flex items-center gap-10 justify-center bg-black/70 z-50">
        <div className=" bg-gradient-to-b from-red-900 to-black p-6 rounded-2xl w-[350px] ">
          <h2 className="text-3xl  font-bold text-orange-500 text-center mb-5">
            ️ Join Battle
          </h2>
          <div className="py-4">
            <input
              type="text"
              placeholder="Enter Player Name"
              value={name}
              onChange={(e) => setName(e.target.value)}
              className=" w-full px-4 py-3 rounded-lg border-2 border-orange-400 bg-gray-800 text-white placeholder-gray-400 focus:outline-none focus:border-orange-500 "
            />
          </div>
          {/* <div>
        <input
          type="text" value={roomCode} placeholder="Enter Room Code" onChange={(e) =>setRoomCode(e.target.value)} className=" w-full px-4 py-3 rounded-lg border-2 border-orange-400 bg-gray-800 text-white placeholder-gray-400 focus:outline-none focus:border-orange-500 " /> </div> */}
          <div className="flex gap-3 mt-5">
            <button
              onClick={()=>HandleJoin(name,setCopied)}
              className=" flex-1 bg-orange-500 text-white py-2 rounded-lg font-semibold hover:bg-orange-600 transition "
            >
              Join
            </button>

            <button
              onClick={onClose}
              className=" flex-1 bg-gray-700 text-white py-2 rounded-lg font-semibold hover:bg-gray-600 transition "
            >
              Cancel
            </button>
          </div>
        </div>
        {copied && <div> Copied the Link </div>}
      </div>
    );
  }
